// Generated by Claude Code on behalf of Benjamin Schwerdtner.
// Pushed only into the test project. Times SCI over 100k cell values (1000x100)
// against a plain JS loop; run through the Apps Script API (scripts.run, devMode).
function gasbbBench() {
  const R = 1000, C = 100;
  globalThis.VALUES = Array.from({length: R}, (_, i) => Array.from({length: C}, (_, j) => i * C + j));
  const cases = [
    ["js: nested for loop sum", () => { let s = 0; for (const r of VALUES) for (const x of r) s += x; return s; }],
    ["sci: loop/recur + aget sum", "(let [v js/VALUES n (alength v)] (loop [i 0 s 0] (if (< i n) (let [r (aget v i) m (alength r)] (recur (inc i) (loop [j 0 s s] (if (< j m) (recur (inc j) (+ s (aget r j))) s)))) s)))"],
    ["sci: reduce over js arrays", "(reduce (fn [s r] (reduce + s r)) 0 js/VALUES)"],
    ["sci: js->clj then reduce", "(reduce (fn [s r] (reduce + s r)) 0 (js->clj js/VALUES))"],
    ["sci: mapv inc per cell", "(count (mapv (fn [r] (mapv inc r)) js/VALUES))"],
    ["sci: doseq + aset in place", "(doseq [r js/VALUES] (dotimes [j (alength r)] (aset r j (* 2 (aget r j)))))"],
  ];
  const t = Date.now(); gasbb.evalString("1"); const init = Date.now() - t;
  return ["context init: " + init + " ms"].concat(cases.map(([name, c]) => {
    const f = typeof c === "function" ? c : () => gasbb.evalString(c);
    const t0 = Date.now(); f(); const cold = Date.now() - t0;
    const ts = [];
    for (let k = 0; k < 5; k++) { const t1 = Date.now(); f(); ts.push(Date.now() - t1); }
    ts.sort((a, b) => a - b);
    return name + ": cold " + cold + " ms, warm median " + ts[2] + " ms";
  }));
}
